function refKotaList(j){const s=new Set();for(const r of REF_IDX)if(r[0]===j&&r[1])s.add(r[1]);for(const k in REF_KOTA){const [a,b]=k.split('|');if(a===j)s.add(b)}return [...s].sort()}
function refPick(){
  const r=S.ref,th=/^\d{4}$/.test(r.tahun)?+r.tahun:0;
  const dist=y=>th&&y?Math.abs(y-th):(y?500:999);
  const cocok=REF_IDX.filter(x=>x[0]===r.jenis&&(!r.kota||x[1]===r.kota)).sort((a,b)=>dist(a[2])-dist(b[2])||b[2]-a[2]);
  const fixes=(REF_KOTA[r.jenis+'|'+r.kota]||[]).slice().sort((a,b)=>dist(a.th)-dist(b.th));
  const vars=REF_TPL[r.jenis];let fix=fixes[0]||null;
  let auto=vars[0].id;
  if(fix)auto=fix.tpl;else if(th&&th<=2008&&vars.some(v=>v.id==='lama'))auto='lama';
  const varId=vars.some(v=>v.id===r.varId)?r.varId:auto;
  if(fix&&fix.tpl!==varId)fix=fixes.find(f=>f.tpl===varId)||null;
  return{cocok,fix,vars,tpl:vars.find(v=>v.id===varId),th};
}
function refFill(tpl,fix,kota){
  const v=Object.assign({},fix?fix.v:{});
  if(kota){if(!v.KOTA)v.KOTA=kota;if(!v.KOTA_TERBIT)v.KOTA_TERBIT=kota}
  return tpl.teks.replace(/\{([A-Z_]+)\}/g,(m,k)=>v[k]||'['+(FIXLBL[k]||k)+']');
}
function refText(p){if(S.ref.teks==null)S.ref.teks=refFill(p.tpl,p.fix,S.ref.kota);return S.ref.teks}
function viewRef(){
  const r=S.ref,p=refPick(),kotas=refKotaList(r.jenis);
  const jopt=Object.entries(REF_JENIS).filter(([k])=>k!=='ktp').map(([k,l])=>`<option value="${k}" ${k===r.jenis?'selected':''}>${l}</option>`).join('');
  const kopt=`<option value="">Semua kota</option>`+kotas.map(k=>`<option ${k===r.kota?'selected':''}>${esc(k)}</option>`).join('');
  const list=p.cocok.slice(0,12).map(x=>`<div class="row" style="padding:8px 14px;border-top:1px solid #F1F2F7"><span class="grow" style="flex:1 1 140px"><b style="font-weight:600">${esc(x[1]||'Kota tidak tertulis')}</b> <span class="small">· ${x[2]||'tahun tidak tertulis'}</span></span>${p.th&&x[2]===p.th?chip('Tahun sama','ok'):''}<a class="btn sm blue" href="https://drive.google.com/file/d/${encodeURIComponent(x[3])}/view" target="_blank" rel="noopener">Buka di Drive</a></div>`).join('');
  const info=!r.kota?chip('Template umum','kosong'):p.fix?chip('Bagian tetap '+r.kota+' terisi','ok')+chip('Nama pejabat dari dokumen '+p.fix.th+' · cek ulang','cek'):chip('Bagian tetap kota ini belum ada · template umum','kosong');
  const vopt=p.vars.map(v=>`<option value="${v.id}" ${v.id===p.tpl.id?'selected':''}>${esc(v.label)}</option>`).join('');
  return head('Referensi kota')+`<div class="split">
  <div class="col" style="flex:1 1 320px;min-width:0;gap:14px">
   <section class="card pad col" aria-label="Cari referensi"><h2>Cari referensi</h2>
    <label class="field">Jenis dokumen<select class="inp" id="refJenis">${jopt}</select></label>
    <label class="field">Kota<select class="inp" id="refKota">${kopt}</select></label>
    <label class="field">Tahun dokumen (opsional)<input class="inp" id="refTahun" type="text" inputmode="numeric" maxlength="4" placeholder="mis. 2005" value="${esc(r.tahun)}" autocomplete="off"></label></section>
   <section class="card" aria-label="Contoh sebelumnya" style="overflow:hidden"><div class="row pad" style="padding-bottom:10px"><h2 class="grow" style="flex:1 1 120px">Contoh sebelumnya</h2><span class="small">${p.cocok.length} file</span></div>
    ${list||`<div style="padding:28px 14px;text-align:center;color:var(--mute);border-top:1px solid #F1F2F7">Belum ada contoh untuk pilihan ini</div>`}
    <div class="small" style="padding:10px 14px;border-top:1px solid var(--soft)">Diurutkan dari tahun terdekat. Indeks demo: ${REF_IDX.length} file terbaru di 247 DRIVE, tanpa nama klien.</div></section>
  </div>
  <section class="card" aria-label="Template" style="flex:2 1 480px;min-width:0;overflow:hidden">
   <div class="row" style="padding:10px 14px;border-bottom:1px solid var(--soft)"><b class="grow" style="flex:1 1 140px">Template ${esc(REF_JENIS[r.jenis])}</b>${p.vars.length>1?`<select class="inp" id="refVar" aria-label="Format" style="width:auto;flex:0 1 220px">${vopt}</select>`:''}</div>
   <div class="row" style="padding:10px 14px 0">${info}</div>
   <div class="pad"><textarea id="refTeks" class="inp" aria-label="Teks template" spellcheck="false" style="min-height:460px;padding:14px;font-family:'Times New Roman',Times,serif;font-size:16px;line-height:1.35;resize:vertical;white-space:pre-wrap">${esc(refText(p))}</textarea></div>
   <div class="row" style="padding:0 14px 14px"><button type="button" class="btn dark" data-ref="docx">${ic(I.down,15)}Unduh DOCX</button><button type="button" class="btn" data-ref="salin">Salin teks</button><button type="button" class="btn" data-ref="reset">Kembalikan template</button></div>
   <div class="small" style="padding:10px 14px;border-top:1px solid var(--soft)">Isi bagian dalam [kurung siku] dari dokumen klien. DOCX: A4, Times New Roman 12, tulisan TRANSLATION di kanan atas. Halaman pernyataan penerjemah terpisah.</div>
  </section></div>`;
}
function textDocx(text){
  const run=(t,b)=>`<w:r><w:rPr><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman" w:cs="Times New Roman"/>${b?'<w:b/>':''}<w:sz w:val="24"/><w:szCs w:val="24"/></w:rPr><w:t xml:space="preserve">${xmlEsc(t)}</w:t></w:r>`;
  const P=(t,jc)=>`<w:p><w:pPr>${jc?`<w:jc w:val="${jc}"/>`:''}<w:spacing w:before="0" w:after="0" w:line="264" w:lineRule="auto"/></w:pPr>${t?run(t):''}</w:p>`;
  const body=P('TRANSLATION','right')+P('')+String(text).replace(/\r/g,'').split('\n').map(l=>P(l)).join('');
  const doc=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>${body}<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440" w:header="708" w:footer="708" w:gutter="0"/></w:sectPr></w:body></w:document>`;
  const z=new PizZip();
  z.file('[Content_Types].xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>');
  z.file('_rels/.rels','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>');
  z.file('word/document.xml',doc);
  return z.generate({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',compression:'DEFLATE'});
}
function refFileName(p){const r=S.ref;const th=p.th?String(p.th).slice(2):'';return [p.tpl.judul,th,r.kota,'[NAMA]'].filter(Boolean).join(' ')+'.docx'}
document.addEventListener('click',async e=>{
  const b=e.target.closest('[data-ref]');if(!b)return;const a=b.dataset.ref,ta=$('#refTeks');
  if(a==='docx'){b.disabled=true;try{await saveFile(refFileName(refPick()),textDocx(ta.value))}finally{b.disabled=false}}
  else if(a==='salin'){try{await navigator.clipboard.writeText(ta.value);toast('Teks disalin')}catch(err){ta.focus();ta.select();toast('Teks sudah diblok. Tekan Ctrl+C untuk menyalin.')}}
  else if(a==='reset'){S.ref.teks=null;render();toast('Template dikembalikan')}
});
document.addEventListener('change',e=>{
  const t=e.target;
  if(t.id==='refJenis'){S.ref.jenis=t.value;S.ref.kota='';S.ref.varId='';S.ref.teks=null;render()}
  else if(t.id==='refKota'){S.ref.kota=t.value;S.ref.varId='';S.ref.teks=null;render()}
  else if(t.id==='refVar'){S.ref.varId=t.value;S.ref.teks=null;render()}
});
document.addEventListener('input',e=>{
  const t=e.target;
  if(t.id==='refTeks')S.ref.teks=t.value;
  else if(t.id==='refTahun'){const v=t.value.replace(/\D/g,'');S.ref.tahun=v;if(v.length===4||v.length===0){S.ref.varId='';S.ref.teks=null;render();const n=$('#refTahun');n.focus();n.setSelectionRange(v.length,v.length)}}
});
